messages.content:
1: """Mindcraft island service: graph model, deterministic check-in, crisis guard, public walkers.
2: 
3: Graph shape: root -> MindIsland -> EmotionalEntity -> InteractionEvent
4:                                    EmotionalEntity -> ValueAction
5: """
6: 
7: node MindIsland {
8:     has name: str = "Mind Island";
9: }
10: 
11: node EmotionalEntity {
12:     has label: str = "";
13:     has emotion: str = "";
14:     has intensity: int = 1;
15:     has shape: str = "stone";
16:     has color: str = "#9ca3af";
17:     has placed: bool = False;
18:     has x: int = 0;
19:     has y: int = 0;
20:     has note: str = "";
21: }
22: 
23: node InteractionEvent {
24:     has kind: str = "";
25:     has result: str = "";
26: }
27: 
28: node ValueAction {
29:     has value: str = "";
30:     has action: str = "";
31: }
32: 
33: glob INTERACTIONS: list[str] = ["breathe", "name", "soften", "listen"];
34: 
35: glob CRISIS_TERMS: list[str] = [
36:     "suicide", "suicidal", "kill myself", "end my life", "want to die",
37:     "hurt myself", "self harm", "self-harm", "no reason to live", "better off dead"
38: ];
39: 
40: glob CRISIS_MESSAGE: str = "It sounds like you may be in danger right now. Please reach out for support immediately: call or text 988 (Suicide and Crisis Lifeline, US), call your local emergency number, or contact someone you trust and tell them how you feel. You do not have to go through this alone.";
41: 
42: glob EMOTION_TABLE: list[dict] = [
43:     {"emotion": "anxiety", "label": "Anxious cloud", "shape": "cloud", "color": "#c7d2fe", "keywords": ["anxious", "anxiety", "worried", "worry", "nervous", "stressed", "stress", "overwhelmed"]},
44:     {"emotion": "sadness", "label": "Heavy stone", "shape": "stone", "color": "#93c5fd", "keywords": ["sad", "down", "lonely", "alone", "empty", "grief", "cry", "hopeless"]},
45:     {"emotion": "anger", "label": "Hot ember", "shape": "ember", "color": "#fca5a5", "keywords": ["angry", "anger", "mad", "furious", "annoyed", "frustrated", "irritated"]},
46:     {"emotion": "fear", "label": "Shadow", "shape": "shadow", "color": "#d4d4d8", "keywords": ["afraid", "scared", "fear", "terrified", "panic"]},
47:     {"emotion": "tiredness", "label": "Drifting log", "shape": "log", "color": "#d6c4a8", "keywords": ["tired", "exhausted", "drained", "burnt out", "burned out", "sleepy"]},
48:     {"emotion": "joy", "label": "Bright flower", "shape": "flower", "color": "#fde68a", "keywords": ["happy", "glad", "joy", "excited", "grateful", "calm", "hopeful"]}
49: ];
50: 
51: glob INTERACTION_RESULTS: dict = {
52:     "breathe": "You took three slow breaths with this feeling beside you.",
53:     "name": "You named the feeling out loud. Naming it gives it a shape you can hold.",
54:     "soften": "You let your shoulders drop. The feeling grew a little lighter.",
55:     "listen": "You asked the feeling what it needs and listened without judging."
56: };
57: 
58: """True when the text contains urgent / crisis language."""
59: def is_crisis(text: str) -> bool {
60:     t = text.lower();
61:     for term in CRISIS_TERMS {
62:         if term in t {
63:             return True;
64:         }
65:     }
66:     return False;
67: }
68: 
69: """Deterministic keyword mapping from free text to feeling specs."""
70: def detect_emotions(text: str) -> list[dict] {
71:     t = text.lower();
72:     intensity = 1;
73:     for amp in ["very", "so ", "really", "extremely", "too "] {
74:         if amp in t {
75:             intensity = intensity + 1;
76:         }
77:     }
78:     if intensity > 3 {
79:         intensity = 3;
80:     }
81:     found: list[dict] = [];
82:     for spec in EMOTION_TABLE {
83:         for kw in spec["keywords"] {
84:             if kw in t {
85:                 found.append({
86:                     "emotion": spec["emotion"],
87:                     "label": spec["label"],
88:                     "shape": spec["shape"],
89:                     "color": spec["color"],
90:                     "intensity": intensity
91:                 });
92:                 break;
93:             }
94:         }
95:     }
96:     if len(found) == 0 {
97:         found.append({
98:             "emotion": "unnamed",
99:             "label": "Unnamed pebble",
100:             "shape": "pebble",
101:             "color": "#cbd5e1",
102:             "intensity": intensity
103:         });
104:     }
105:     return found;
106: }
107: 
108: """Plain dict projection of an entity for the client."""
109: def entity_view(e: EmotionalEntity) -> dict {
110:     return {
111:         "id": jid(e),
112:         "label": e.label,
113:         "emotion": e.emotion,
114:         "intensity": e.intensity,
115:         "shape": e.shape,
116:         "color": e.color,
117:         "placed": e.placed,
118:         "x": e.x,
119:         "y": e.y,
120:         "note": e.note
121:     };
122: }
123: 
124: """Get-or-create the island attached to the given root."""
125: def get_island(r: Root) -> MindIsland {
126:     islands = [r -->[?:MindIsland]];
127:     if len(islands) > 0 {
128:         return islands[0];
129:     }
130:     island = MindIsland();
131:     r ++> island;
132:     return island;
133: }
134: 
135: """Resolve an entity id to an EmotionalEntity, or None."""
136: def find_entity(entity_id: str) -> EmotionalEntity | None {
137:     if not entity_id {
138:         return None;
139:     }
140:     found: any = None;
141:     try {
142:         found = jobj(entity_id);
143:     } except Exception {
144:         return None;
145:     }
146:     if isinstance(found, EmotionalEntity) {
147:         return found;
148:     }
149:     return None;
150: }
151: 
152: def clamp(v: int) -> int {
153:     if v < 5 {
154:         return 5;
155:     }
156:     if v > 95 {
157:         return 95;
158:     }
159:     return v;
160: }
161: 
162: walker:pub get_world {
163:     has reports: list[dict] = [];
164: 
165:     can run with Root entry {
166:         island = get_island(here);
167:         entities = [island -->[?:EmotionalEntity]];
168:         report {
169:             "entities": [entity_view(e) for e in entities],
170:             "interactions": INTERACTIONS
171:         };
172:     }
173: }
174: 
175: walker:pub manifest_emotion {
176:     has text: str = "";
177:     has reports: list[dict] = [];
178: 
179:     can run with Root entry {
180:         t = self.text.strip();
181:         if not t {
182:             report {"crisis": False, "error": "Describe how you feel first.", "message": "", "entities": []};
183:             disengage;
184:         }
185:         if is_crisis(t) {
186:             report {"crisis": True, "message": CRISIS_MESSAGE, "entities": []};
187:             disengage;
188:         }
189:         island = get_island(here);
190:         created: list[dict] = [];
191:         for spec in detect_emotions(t) {
192:             e = EmotionalEntity(
193:                 label=spec["label"],
194:                 emotion=spec["emotion"],
195:                 intensity=spec["intensity"],
196:                 shape=spec["shape"],
197:                 color=spec["color"],
198:                 note=t
199:             );
200:             island ++> e;
201:             created.append(entity_view(e));
202:         }
203:         report {"crisis": False, "message": "", "entities": created};
204:     }
205: }
206: 
207: walker:pub place_entity {
208:     has entity_id: str = "";
209:     has x: int = 0;
210:     has y: int = 0;
211:     has reports: list[dict] = [];
212: 
213:     can run with Root entry {
214:         e = find_entity(self.entity_id);
215:         if e is None {
216:             report {"error": "Feeling not found."};
217:             disengage;
218:         }
219:         e.placed = True;
220:         e.x = clamp(self.x);
221:         e.y = clamp(self.y);
222:         report {"entity": entity_view(e)};
223:     }
224: }
225: 
226: walker:pub apply_interaction {
227:     has entity_id: str = "";
228:     has kind: str = "";
229:     has reports: list[dict] = [];
230: 
231:     can run with Root entry {
232:         e = find_entity(self.entity_id);
233:         if e is None {
234:             report {"error": "Feeling not found."};
235:             disengage;
236:         }
237:         if not e.placed {
238:             report {"error": "Place the feeling on the island first."};
239:             disengage;
240:         }
241:         if self.kind not in INTERACTIONS {
242:             report {"error": "Unknown interaction."};
243:             disengage;
244:         }
245:         if self.kind == "soften" and e.intensity > 1 {
246:             e.intensity = e.intensity - 1;
247:         }
248:         result = INTERACTION_RESULTS[self.kind];
249:         ev = InteractionEvent(kind=self.kind, result=result);
250:         e ++> ev;
251:         report {"entity": entity_view(e), "event": {"kind": ev.kind, "result": ev.result}};
252:     }
253: }
254: 
255: walker:pub commit_value_action {
256:     has entity_id: str = "";
257:     has value: str = "";
258:     has action: str = "";
259:     has reports: list[dict] = [];
260: 
261:     can run with Root entry {
262:         e = find_entity(self.entity_id);
263:         if e is None {
264:             report {"error": "Feeling not found."};
265:             disengage;
266:         }
267:         if not e.placed {
268:             report {"error": "Place the feeling on the island first."};
269:             disengage;
270:         }
271:         v = self.value.strip();
272:         a = self.action.strip();
273:         if not v or not a {
274:             report {"error": "Add both what matters to you and one concrete next action."};
275:             disengage;
276:         }
277:         va = ValueAction(value=v, action=a);
278:         e ++> va;
279:         report {"entity": entity_view(e), "action": {"value": va.value, "action": va.action}};
280:     }
281: }
282: 
283: walker:pub get_act_path {
284:     has entity_id: str = "";
285:     has reports: list[dict] = [];
286: 
287:     can run with Root entry {
288:         e = find_entity(self.entity_id);
289:         if e is None {
290:             report {"error": "Feeling not found."};
291:             disengage;
292:         }
293:         events = [e -->[?:InteractionEvent]];
294:         actions = [e -->[?:ValueAction]];
295:         report {
296:             "entity": entity_view(e),
297:             "events": [{"kind": ev.kind, "result": ev.result} for ev in events],
298:             "actions": [{"value": va.value, "action": va.action} for va in actions]
299:         };
300:     }
301: }
302: 
303: walker:pub reset_demo {
304:     has reports: list[dict] = [];
305: 
306:     can run with Root entry {
307:         island = get_island(here);
308:         entities = [island -->[?:EmotionalEntity]];
309:         cleared = len(entities);
310:         for e in entities {
311:             for ev in [e -->[?:InteractionEvent]] {
312:                 del ev;
313:             }
314:             for va in [e -->[?:ValueAction]] {
315:                 del va;
316:             }
317:             del e;
318:         }
319:         report {"cleared": cleared};
320:     }
321: }

1: """Mindcraft single-page check-in UI: island, check-in form, interactions, intention and path."""
2: 
3: cl {
4:     sv import from ..services.island {
5:         get_world,
6:         manifest_emotion,
7:         place_entity,
8:         apply_interaction,
9:         commit_value_action,
10:         get_act_path,
11:         reset_demo
12:     }
13: 
14:     def:pub MindcraftApp() -> JsxElement {
15:         has entities: list[dict] = [];
16:         has interactions: list[str] = [];
17:         has text: str = "";
18:         has crisisMsg: str = "";
19:         has selectedId: str = "";
20:         has value: str = "";
21:         has action: str = "";
22:         has pathEvents: list[dict] = [];
23:         has pathActions: list[dict] = [];
24:         has pathLoaded: bool = False;
25:         has notice: str = "";
26:         has error: str = "";
27:         has loading: bool = True;
28:         has busy: bool = False;
29: 
30:         async def load_world() -> None {
31:             try {
32:                 result = root spawn get_world();
33:                 if result.reports and len(result.reports) > 0 {
34:                     data = result.reports[0];
35:                     entities = data["entities"];
36:                     interactions = data["interactions"];
37:                 }
38:             } except Exception as ex {
39:                 error = "Could not load the island. Try refreshing.";
40:             }
41:             loading = False;
42:         }
43: 
44:         async can with entry {
45:             await load_world();
46:         }
47: 
48:         async def load_path(eid: str) -> None {
49:             result = root spawn get_act_path(entity_id=eid);
50:             if result.reports and len(result.reports) > 0 {
51:                 data = result.reports[0];
52:                 if data["error"] {
53:                     error = str(data["error"]);
54:                 } else {
55:                     pathEvents = data["events"];
56:                     pathActions = data["actions"];
57:                     pathLoaded = True;
58:                 }
59:             }
60:         }
61: 
62:         async def check_in() -> None {
63:             error = "";
64:             notice = "";
65:             crisisMsg = "";
66:             if not text.strip() {
67:                 error = "Describe how you feel first.";
68:                 return;
69:             }
70:             busy = True;
71:             result = root spawn manifest_emotion(text=text);
72:             if result.reports and len(result.reports) > 0 {
73:                 data = result.reports[0];
74:                 if data["crisis"] {
75:                     crisisMsg = str(data["message"]);
76:                 } elif data["error"] {
77:                     error = str(data["error"]);
78:                 } else {
79:                     notice = str(len(data["entities"])) + " feeling(s) arrived. Place them on the island.";
80:                     text = "";
81:                 }
82:             }
83:             await load_world();
84:             busy = False;
85:         }
86: 
87:         async def select(eid: str) -> None {
88:             selectedId = eid;
89:             pathEvents = [];
90:             pathActions = [];
91:             pathLoaded = False;
92:             error = "";
93:             await load_path(eid);
94:         }
95: 
96:         async def place(eid: str, idx: int) -> None {
97:             error = "";
98:             px = 20 + (idx * 23) % 60;
99:             py = 30 + (idx * 17) % 40;
100:             result = root spawn place_entity(entity_id=eid, x=px, y=py);
101:             if result.reports and len(result.reports) > 0 {
102:                 data = result.reports[0];
103:                 if data["error"] {
104:                     error = str(data["error"]);
105:                 }
106:             }
107:             selectedId = eid;
108:             await load_world();
109:             await load_path(eid);
110:         }
111: 
112:         async def interact(kind: str) -> None {
113:             error = "";
114:             result = root spawn apply_interaction(entity_id=selectedId, kind=kind);
115:             if result.reports and len(result.reports) > 0 {
116:                 data = result.reports[0];
117:                 if data["error"] {
118:                     error = str(data["error"]);
119:                 } else {
120:                     notice = str(data["event"]["result"]);
121:                 }
122:             }
123:             await load_world();
124:             await load_path(selectedId);
125:         }
126: 
127:         async def commit() -> None {
128:             error = "";
129:             result = root spawn commit_value_action(entity_id=selectedId, value=value, action=action);
130:             if result.reports and len(result.reports) > 0 {
131:                 data = result.reports[0];
132:                 if data["error"] {
133:                     error = str(data["error"]);
134:                 } else {
135:                     notice = "Next action saved: " + str(data["action"]["action"]);
136:                     value = "";
137:                     action = "";
138:                 }
139:             }
140:             await load_path(selectedId);
141:         }
142: 
143:         async def reset() -> None {
144:             error = "";
145:             crisisMsg = "";
146:             result = root spawn reset_demo();
147:             if result.reports and len(result.reports) > 0 {
148:                 notice = "Island cleared (" + str(result.reports[0]["cleared"]) + " feeling(s) released).";
149:             }
150:             selectedId = "";
151:             pathEvents = [];
152:             pathActions = [];
153:             pathLoaded = False;
154:             await load_world();
155:         }
156: 
157:         def on_text(e: ChangeEvent) { text = e.target.value; }
158:         def on_value(e: ChangeEvent) { value = e.target.value; }
159:         def on_action(e: ChangeEvent) { action = e.target.value; }
160: 
161:         pending = [en for en in entities if not en["placed"]];
162:         placed = [en for en in entities if en["placed"]];
163:         selected: dict | None = None;
164:         for en in entities {
165:             if en["id"] == selectedId {
166:                 selected = en;
167:             }
168:         }
169:         selected_placed: bool = selected is not None and selected["placed"];
170:         selected_label: str = str(selected["label"]) if selected is not None else "";
171:         selected_note: str = str(selected["note"]) if selected is not None else "";
172: 
173:         return <main className="mc-shell">
174:             <header className="mc-header">
175:                 <h1>Mindcraft</h1>
176:                 <p>Name how you feel, give it a place on your island, and choose one gentle next step.</p>
177:             </header>
178:             {crisisMsg and <div className="mc-crisis" role="alert">
179:                 <strong>You deserve support right now.</strong>
180:                 <p>{crisisMsg}</p>
181:             </div>}
182:             <div className="mc-grid">
183:                 <section className="mc-card">
184:                     <div className="mc-row" style={{"justifyContent": "space-between", "alignItems": "center"}}>
185:                         <h2>Your island</h2>
186:                         <button className="mc-btn" onClick={lambda { reset(); }}>Reset island</button>
187:                     </div>
188:                     <div className="mc-island" data-testid="island">
189:                         {if loading {
190:                             <div className="mc-island-empty">Loading your island...</div>
191:                         } elif len(placed) == 0 {
192:                             <div className="mc-island-empty">
193:                                 <strong>Your island is empty</strong>
194:                                 <span>Check in below, then place a feeling here.</span>
195:                             </div>
196:                         }}
197:                         {for en in placed {
198:                             <button
199:                                 key={str(en["id"])}
200:                                 className={"mc-entity is-selected" if en["id"] == selectedId else "mc-entity"}
201:                                 style={{"left": str(en["x"]) + "%", "top": str(en["y"]) + "%", "background": en["color"]}}
202:                                 onClick={lambda { select(str(en["id"])); }}
203:                             >{str(en["label"]) + " (" + str(en["intensity"]) + ")"}</button>
204:                         }}
205:                     </div>
206:                     <div className="mc-stack" style={{"marginTop": "12px"}}>
207:                         <span className="mc-label">Gentle interactions</span>
208:                         <div className="mc-row">
209:                             {for k in interactions {
210:                                 <button key={k} className="mc-btn" disabled={not selected_placed} onClick={lambda { interact(k); }}>{k}</button>
211:                             }}
212:                         </div>
213:                         {if not selected_placed {
214:                             <span className="mc-muted">Select a placed feeling to try an interaction.</span>
215:                         }}
216:                     </div>
217:                 </section>
218:                 <aside className="mc-stack">
219:                     <section className="mc-card mc-stack">
220:                         <h2>Check in</h2>
221:                         <label className="mc-label" htmlFor="feel">How are you feeling?</label>
222:                         <textarea id="feel" className="mc-textarea" placeholder="I feel anxious about tomorrow and a bit tired" value={text} onChange={on_text} />
223:                         <button className="mc-btn mc-btn-primary" disabled={busy} onClick={lambda { check_in(); }}>Add check-in</button>
224:                         {error and <span className="mc-error">{error}</span>}
225:                         {notice and <span className="mc-muted">{notice}</span>}
226:                     </section>
227:                     <section className="mc-card mc-stack">
228:                         <h2>Waiting to be placed</h2>
229:                         {if len(pending) == 0 {
230:                             <span className="mc-muted">No pending feelings.</span>
231:                         }}
232:                         <div className="mc-pending">
233:                             {for (i, en) in enumerate(pending) {
234:                                 <button key={str(en["id"])} className="mc-chip" onClick={lambda { place(str(en["id"]), len(placed) + i); }}>{"Place " + str(en["label"])}</button>
235:                             }}
236:                         </div>
237:                     </section>
238:                     {selected_placed and <section className="mc-card mc-stack">
239:                         <h2>{"Next step for " + selected_label}</h2>
240:                         <label className="mc-label" htmlFor="val">What matters to you here?</label>
241:                         <input id="val" className="mc-input" placeholder="Being prepared" value={value} onChange={on_value} />
242:                         <label className="mc-label" htmlFor="act">One concrete next action</label>
243:                         <input id="act" className="mc-input" placeholder="Write three bullet points for tomorrow" value={action} onChange={on_action} />
244:                         <button className="mc-btn mc-btn-primary" onClick={lambda { commit(); }}>Commit intention</button>
245:                         <span className="mc-label">Path</span>
246:                         {if pathLoaded and len(pathEvents) == 0 and len(pathActions) == 0 {
247:                             <span className="mc-muted">Placed. No interactions or intentions yet.</span>
248:                         }}
249:                         <ol className="mc-path">
250:                             <li>{"Felt: " + selected_note}</li>
251:                             <li>Placed on the island</li>
252:                             {for (i, ev) in enumerate(pathEvents) {
253:                                 <li key={"ev" + str(i)}>{"Tried " + str(ev["kind"]) + ": " + str(ev["result"])}</li>
254:                             }}
255:                             {for (i, va) in enumerate(pathActions) {
256:                                 <li key={"va" + str(i)}>{"Intention (" + str(va["value"]) + "): " + str(va["action"])}</li>
257:                             }}
258:                         </ol>
259:                     </section>}
260:                 </aside>
261:             </div>
262:         </main>;
263:     }
264: }

1: """Mindcraft entry: registers the island walkers as server endpoints and mounts the single-page client."""
2: 
3: import from services.island {
4:     MindIsland,
5:     EmotionalEntity,
6:     InteractionEvent,
7:     ValueAction,
8:     get_world,
9:     manifest_emotion,
10:     place_entity,
11:     apply_interaction,
12:     commit_value_action,
13:     get_act_path,
14:     reset_demo
15: }
16: 
17: cl {
18:     import "./styles.css";
19:     import from .components.MindcraftApp { MindcraftApp }
20: 
21:     def:pub app() -> JsxElement {
22:         return <MindcraftApp />;
23:     }
24: }

[jac-skill loaded: jac-testing @ jac 0.34.27]

Tests are first-class language blocks written alongside the code they test - `jac run` ignores them; `jac test` runs them. All checks are plain `assert` statements, with an optional message: `assert user.is_valid(), f"bad user: {user.name}";`.

```jac
obj User {
    has name: str, email: str;

    def is_valid() -> bool { return "@" in self.email; }
}

test "user is valid" {
    user = User(name="Alice", email="alice@example.com");
    assert user.is_valid();
}
```

## Running tests

```
jac test main.jac                 # all tests in a file
jac test                          # all tests in current directory
jac test -d tests/                # all tests in a directory
jac test main.jac -t "my test"    # one test by name (quote multi-word names)
jac test -d tests/ -f "user*"     # filter test FILES by Unix pattern
jac test main.jac -x              # stop on first failure
jac test main.jac -m 3            # stop after 3 failures
jac test main.jac -v              # verbose (one line per test)
```

A `test "some name"` block becomes unittest case `test_some_name` (spaces -> underscores). Defaults live in the `[test]` section of jac.toml (`directory`, `filter`, `verbose`, `fail_fast`, `max_failures`).

## File naming - two traps

- **Never name files `test_*.jac`** (e.g. `test_utils.jac`) - the `test_` prefix collides with Python's test-module import machinery. Use `utils_tests.jac`, or the annex form below.
- **`<mod>.test.jac` is an ANNEX, not a standalone file.** Like `.impl.jac`, it attaches to a same-basename module: `people.test.jac` pairs with `people.jac`, and you run `jac test people.jac`. A `.test.jac` with no base module fails with `No module named '<mod>'`. The annex sees the module's declarations without imports - ideal for keeping tests out of the main file.

## Graph state: tests share a persisted root

Verified behavior: tests in a file run **in declaration order against one shared `root`**, and anything hung off `root` also **persists to `.jac/data` between runs**. Two consequences:

- A later test sees nodes created by an earlier test in the same run.
- A green suite can go red on re-run because last run's nodes are still there - or crash with `NodeAnchor <id> is not a valid reference` when stale persisted anchors meet recompiled code.

Fix both the same way: `jac clean --all --force` (or `jac clean --data`) before the run. Write graph assertions defensively - count nodes you just created (or filter by a unique field) rather than asserting totals on `root`.

## Testing walkers: spawn + `.reports`

```jac
node Person { has name: str; has age: int; }

walker FindAdults {
    can check with Root entry {
        for p in [-->][?:Person] {
            if p.age >= 18 { report p; }
        }
    }
}

test "finds adults only" {
    root ++> Person(name="Alice", age=30);
    root ++> Person(name="Bob", age=15);
    result = root spawn FindAdults();
    assert len(result.reports) == 1;
    assert result.reports[0].name == "Alice";
}
```

The spawn expression returns the walker instance; every `report` it made is in `result.reports` (a list, in report order). Assert graph shape directly too: `assert len([root-->]) == 2;`, `assert alice in [root ->:Friend:->];`.

## Expecting an exception

No `pytest.raises` - use try/except with a guard assert:

```jac
test "divide by zero raises" {
    try {
        divide(10, 0);
        assert False, "should have raised";
    } except ZeroDivisionError {
        assert True;
    }
}
```

## Parameterized tests

`parametrize()` registers one test per input, in a `with entry` block:

```jac
import from jaclang.runtimelib.test { parametrize }

def _test_square(pair: tuple) {
    assert pair[0] ** 2 == pair[1];
}

with entry {
    parametrize("square", [(2, 4), (3, 9), (0, 0)], _test_square);
}
```

Each case runs and reports independently (`square_0`, `square_1`, ...); pass `id_fn=` to name cases from their parameter.

## In-process endpoint tests: JacTestClient

For testing served endpoints (`walker:pub` / `def:pub`) without starting a real server, use the Python-side client from pytest:

```python
from jaclang.runtimelib.testing import JacTestClient

def test_task_crud(tmp_path):
    client = JacTestClient.from_file("app.jac", base_path=str(tmp_path))
    client.register_user("testuser", "password123")            # auth in one line
    resp = client.post("/walker/CreateTask", json={"title": "My Task"})
    assert resp.ok and resp.status_code == 200
    assert len(client.post("/walker/GetTasks").json()["reports"]) == 1
    client.close()
```

`base_path=tmp_path` keeps each test's persisted graph isolated. Also available: `get/put/request`, `login`, `set_auth_token`, `resp.data` (unwrapped envelope), `client.reload()` (HMR).

## Pitfalls

- **`-f` filters test FILES (Unix glob on filenames), `-t` selects one test by name.** They are not interchangeable. `-t` without a filepath/directory is an error.
- **LLM-powered functions**: don't hit a real model in tests - use `MockLLM` with canned outputs (see `jac-by-llm`).

## See also

- `jac-debugging` - the check/fix loop, stale-cache triage (`jac clean` vs `jac purge`)
- `jac-config` - `[test]` defaults, `[scripts]` (`test = "jac test -v"`)
- `jac-walker-patterns` - report/reports semantics being asserted here

