test "fresh visit shows empty island and interactions" {
    root spawn reset_demo();
    res = root spawn get_world();
    assert len(res.reports) == 1;
    data = res.reports[0];
    assert len(data["entities"]) == 0;
    assert len(data["interactions"]) == 4;
    assert "breathe" in data["interactions"];
}

test "check-in creates pending feelings" {
    root spawn reset_demo();
    res = root spawn manifest_emotion(text="I feel anxious and very tired today");
    data = res.reports[0];
    assert not data["crisis"];
    ents: list[dict] = data["entities"] as list[dict];
    assert len(ents) == 2;
    for e in ents {
        assert not e["placed"];
    }
    world = (root spawn get_world()).reports[0];
    assert len(world["entities"]) == 2;
}

test "unrecognised text still creates one feeling" {
    root spawn reset_demo();
    data = (root spawn manifest_emotion(text="hard to describe")).reports[0];
    assert len(data["entities"]) == 1;
    assert data["entities"][0]["emotion"] == "unnamed";
}

test "place, interact, commit intention and view path" {
    root spawn reset_demo();
    created = (root spawn manifest_emotion(text="I am so worried about tomorrow")).reports[0]["entities"];
    eid: str = str(created[0]["id"]);
    early = (root spawn apply_interaction(entity_id=eid, kind="breathe")).reports[0];
    assert "error" in early;
    placed = (root spawn place_entity(entity_id=eid, x=200, y=40)).reports[0];
    assert placed["entity"]["placed"];
    assert placed["entity"]["x"] == 95;
    inter = (root spawn apply_interaction(entity_id=eid, kind="soften")).reports[0];
    assert inter["event"]["kind"] == "soften";
    bad = (root spawn apply_interaction(entity_id=eid, kind="shout")).reports[0];
    assert "error" in bad;
    empty = (root spawn commit_value_action(entity_id=eid, value="", action="")).reports[0];
    assert "error" in empty;
    committed = (root spawn commit_value_action(entity_id=eid, value="Being prepared", action="Write three notes")).reports[0];
    assert committed["action"]["action"] == "Write three notes";
    path = (root spawn get_act_path(entity_id=eid)).reports[0];
    assert len(path["events"]) == 1;
    assert len(path["actions"]) == 1;
    assert path["actions"][0]["value"] == "Being prepared";
}

test "crisis language creates no feeling" {
    root spawn reset_demo();
    data = (root spawn manifest_emotion(text="I want to die")).reports[0];
    assert data["crisis"];
    assert "988" in data["message"];
    assert len(data["entities"]) == 0;
    world = (root spawn get_world()).reports[0];
    assert len(world["entities"]) == 0;
}

test "reset clears the island" {
    root spawn reset_demo();
    root spawn manifest_emotion(text="sad and angry");
    cleared = (root spawn reset_demo()).reports[0];
    assert cleared["cleared"] == 2;
    world = (root spawn get_world()).reports[0];
    assert len(world["entities"]) == 0;
}

test "unknown entity id reports error" {
    data = (root spawn place_entity(entity_id="missing", x=10, y=10)).reports[0];
    assert "error" in data;
}
"}

