1: """Mindcraft island service: graph model, deterministic check-in, crisis guard, public walkers.
2: 
3: Graph shape: root -> MindIsland -> EmotionalEntity -> InteractionEvent
4:                                    EmotionalEntity -> ValueAction
5: """
6: 
7: node MindIsland {
8:     has name: str = "Mind Island";
9: }
10: 
11: node EmotionalEntity {
12:     has label: str = "";
13:     has emotion: str = "";
14:     has intensity: int = 1;
15:     has shape: str = "stone";
16:     has color: str = "#9ca3af";
17:     has placed: bool = False;
18:     has x: int = 0;
19:     has y: int = 0;
20:     has note: str = "";
21: }
22: 
23: node InteractionEvent {
24:     has kind: str = "";
25:     has result: str = "";
26: }
27: 
28: node ValueAction {
29:     has value: str = "";
30:     has action: str = "";
31: }
32: 
33: glob INTERACTIONS: list[str] = ["breathe", "name", "soften", "listen"];
34: 
35: glob CRISIS_TERMS: list[str] = [
36:     "suicide", "suicidal", "kill myself", "end my life", "want to die",
37:     "hurt myself", "self harm", "self-harm", "no reason to live", "better off dead"
38: ];
39: 
40: glob CRISIS_MESSAGE: str = "It sounds like you may be in danger right now. Please reach out for support immediately: call or text 988 (Suicide and Crisis Lifeline, US), call your local emergency number, or contact someone you trust and tell them how you feel. You do not have to go through this alone.";
41: 
42: glob EMOTION_TABLE: list[dict] = [
43:     {"emotion": "anxiety", "label": "Anxious cloud", "shape": "cloud", "color": "#c7d2fe", "keywords": ["anxious", "anxiety", "worried", "worry", "nervous", "stressed", "stress", "overwhelmed"]},
44:     {"emotion": "sadness", "label": "Heavy stone", "shape": "stone", "color": "#93c5fd", "keywords": ["sad", "down", "lonely", "alone", "empty", "grief", "cry", "hopeless"]},
45:     {"emotion": "anger", "label": "Hot ember", "shape": "ember", "color": "#fca5a5", "keywords": ["angry", "anger", "mad", "furious", "annoyed", "frustrated", "irritated"]},
46:     {"emotion": "fear", "label": "Shadow", "shape": "shadow", "color": "#d4d4d8", "keywords": ["afraid", "scared", "fear", "terrified", "panic"]},
47:     {"emotion": "tiredness", "label": "Drifting log", "shape": "log", "color": "#d6c4a8", "keywords": ["tired", "exhausted", "drained", "burnt out", "burned out", "sleepy"]},
48:     {"emotion": "joy", "label": "Bright flower", "shape": "flower", "color": "#fde68a", "keywords": ["happy", "glad", "joy", "excited", "grateful", "calm", "hopeful"]}
49: ];
50: 
51: glob INTERACTION_RESULTS: dict = {
52:     "breathe": "You took three slow breaths with this feeling beside you.",
53:     "name": "You named the feeling out loud. Naming it gives it a shape you can hold.",
54:     "soften": "You let your shoulders drop. The feeling grew a little lighter.",
55:     "listen": "You asked the feeling what it needs and listened without judging."
56: };
57: 
58: """True when the text contains urgent / crisis language."""
59: def is_crisis(text: str) -> bool {
60:     t = text.lower();
61:     for term in CRISIS_TERMS {
62:         if term in t {
63:             return True;
64:         }
65:     }
66:     return False;
67: }
68: 
69: """Deterministic keyword mapping from free text to feeling specs."""
70: def detect_emotions(text: str) -> list[dict] {
71:     t = text.lower();
72:     intensity = 1;
73:     for amp in ["very", "so ", "really", "extremely", "too "] {
74:         if amp in t {
75:             intensity = intensity + 1;
76:         }
77:     }
78:     if intensity > 3 {
79:         intensity = 3;
80:     }
81:     found: list[dict] = [];
82:     for spec in EMOTION_TABLE {
83:         kws: list[str] = spec["keywords"] as list[str];
84:         for kw in kws {
85:             if kw in t {
86:                 found.append({
87:                     "emotion": spec["emotion"],
88:                     "label": spec["label"],
89:                     "shape": spec["shape"],
90:                     "color": spec["color"],
91:                     "intensity": intensity
92:                 });
93:                 break;
94:             }
95:         }
96:     }
97:     if len(found) == 0 {
98:         found.append({
99:             "emotion": "unnamed",
100:             "label": "Unnamed pebble",
101:             "shape": "pebble",
102:             "color": "#cbd5e1",
103:             "intensity": intensity
104:         });
105:     }
106:     return found;
107: }
108: 
109: """Plain dict projection of an entity for the client."""
110: def entity_view(e: EmotionalEntity) -> dict {
111:     return {
112:         "id": jid(e),
113:         "label": e.label,
114:         "emotion": e.emotion,
115:         "intensity": e.intensity,
116:         "shape": e.shape,
117:         "color": e.color,
118:         "placed": e.placed,
119:         "x": e.x,
120:         "y": e.y,
121:         "note": e.note
122:     };
123: }
124: 
125: """Get-or-create the island attached to the given root."""
126: def get_island(r: Root) -> MindIsland {
127:     islands = [r -->[?:MindIsland]];
128:     if len(islands) > 0 {
129:         return islands[0];
130:     }
131:     island = MindIsland();
132:     r ++> island;
133:     return island;
134: }
135: 
136: """Resolve an entity id to an EmotionalEntity, or None."""
137: def find_entity(entity_id: str) -> EmotionalEntity | None {
138:     if not entity_id {
139:         return None;
140:     }
141:     found: any = None;
142:     try {
143:         found = jobj(entity_id);
144:     } except Exception {
145:         return None;
146:     }
147:     if isinstance(found, EmotionalEntity) {
148:         return found;
149:     }
150:     return None;
151: }
152: 
153: def clamp(v: int) -> int {
154:     if v < 5 {
155:         return 5;
156:     }
157:     if v > 95 {
158:         return 95;
159:     }
160:     return v;
161: }
162: 
163: walker:pub get_world {
164:     has reports: list[dict] = [];
165: 
166:     can run with Root entry {
167:         island = get_island(here);
168:         entities = [island -->[?:EmotionalEntity]];
169:         report {
170:             "entities": [entity_view(e) for e in entities],
171:             "interactions": INTERACTIONS
172:         };
173:     }
174: }
