176: walker:pub manifest_emotion {
177:     has text: str = "";
178:     has reports: list[dict] = [];
179: 
180:     can run with Root entry {
181:         t = self.text.strip();
182:         if not t {
183:             report {"crisis": False, "error": "Describe how you feel first.", "message": "", "entities": []};
184:             disengage;
185:         }
186:         if is_crisis(t) {
