196:                 intensity=spec["intensity"],
197:                 shape=spec["shape"],
198:                 color=spec["color"],
199:                 note=t
200:             );
201:             island ++> e;
202:             created.append(entity_view(e));
203:         }
204:         report {"crisis": False, "message": "", "entities": created};
205:     }
206: }
