1: """Mindcraft single-page check-in UI: island, check-in form, interactions, intention and path."""
2: 
3: sv import from ..services.island {
4:     get_world,
5:     manifest_emotion,
6:     place_entity,
7:     apply_interaction,
8:     commit_value_action,
9:     get_act_path,
10:     reset_demo
11: }
12: 
13: def:pub MindcraftApp() -> JsxElement {
14:     has entities: list[dict] = [];
15:     has interactions: list[str] = [];
16:     has text: str = "";
17:     has crisisMsg: str = "";
18:     has selectedId: str = "";
19:     has value: str = "";
20:     has action: str = "";
21:     has pathEvents: list[dict] = [];
22:     has pathActions: list[dict] = [];
23:     has pathLoaded: bool = False;
24:     has notice: str = "";
25:     has error: str = "";
26:     has loading: bool = True;
27:     has busy: bool = False;
28: 
29:     async def load_world() -> None {
30:         try {
31:             result = root spawn get_world();
32:             if result.reports and len(result.reports) > 0 {
33:                 data = result.reports[0];
34:                 entities = data["entities"];
35:                 interactions = data["interactions"];
36:             }
37:         } except Exception {
38:             error = "Could not load the island. Try refreshing.";
39:         }
40:         loading = False;
41:     }
42: 
43:     async can with entry {
44:         await load_world();
45:     }
46: 
47:     async def load_path(eid: str) -> None {
48:         result = root spawn get_act_path(entity_id=eid);
49:         if result.reports and len(result.reports) > 0 {
50:             data = result.reports[0];
51:             if data["error"] {
52:                 error = str(data["error"]);
53:             } else {
54:                 pathEvents = data["events"];
55:                 pathActions = data["actions"];
56:                 pathLoaded = True;
57:             }
58:         }
59:     }
60: 
61:     async def check_in() -> None {
62:         error = "";
63:         notice = "";
64:         crisisMsg = "";
65:         if not text.strip() {
66:             error = "Describe how you feel first.";
67:             return;
68:         }
69:         busy = True;
70:         result = root spawn manifest_emotion(text=text);
71:         if result.reports and len(result.reports) > 0 {
72:             data = result.reports[0];
73:             if data["crisis"] {
74:                 crisisMsg = str(data["message"]);
75:             } elif data["error"] {
76:                 error = str(data["error"]);
77:             } else {
78:                 notice = str(len(data["entities"])) + " feeling(s) arrived. Place them on the island.";
79:                 text = "";
80:             }
81:         }
82:         await load_world();
83:         busy = False;
84:     }
85: 
86:     async def select(eid: str) -> None {
87:         selectedId = eid;
88:         pathEvents = [];
89:         pathActions = [];
90:         pathLoaded = False;
91:         error = "";
92:         await load_path(eid);
93:     }
94: 
95:     async def place(eid: str, idx: int) -> None {
96:         error = "";
97:         px = 20 + (idx * 23) % 60;
98:         py = 30 + (idx * 17) % 40;
99:         result = root spawn place_entity(entity_id=eid, x=px, y=py);
100:         if result.reports and len(result.reports) > 0 {
101:             data = result.reports[0];
102:             if data["error"] {
103:                 error = str(data["error"]);
104:             }
105:         }
106:         selectedId = eid;
107:         await load_world();
108:         await load_path(eid);
109:     }
110: 
111:     async def interact(kind: str) -> None {
112:         error = "";
113:         result = root spawn apply_interaction(entity_id=selectedId, kind=kind);
114:         if result.reports and len(result.reports) > 0 {
115:             data = result.reports[0];
116:             if data["error"] {
117:                 error = str(data["error"]);
118:             } else {
119:                 notice = str(data["event"]["result"]);
120:             }
121:         }
122:         await load_world();
123:         await load_path(selectedId);
124:     }
125: 
126:     async def commit() -> None {
127:         error = "";
128:         result = root spawn commit_value_action(entity_id=selectedId, value=value, action=action);
129:         if result.reports and len(result.reports) > 0 {
130:             data = result.reports[0];
131:             if data["error"] {
132:                 error = str(data["error"]);
133:             } else {
134:                 notice = "Next action saved: " + str(data["action"]["action"]);
135:                 value = "";
136:                 action = "";
137:             }
138:         }
139:         await load_path(selectedId);
140:     }
141: 
142:     async def reset() -> None {
143:         error = "";
144:         crisisMsg = "";
145:         result = root spawn reset_demo();
146:         if result.reports and len(result.reports) > 0 {
147:             notice = "Island cleared (" + str(result.reports[0]["cleared"]) + " feeling(s) released).";
148:         }
149:         selectedId = "";
150:         pathEvents = [];
151:         pathActions = [];
152:         pathLoaded = False;
153:         await load_world();
154:     }
155: 
156:     def on_text(e: ChangeEvent) { text = e.target.value; }
157:     def on_value(e: ChangeEvent) { value = e.target.value; }
158:     def on_action(e: ChangeEvent) { action = e.target.value; }
159: 
160:     pending = [en for en in entities if not en["placed"]];
161:     placed = [en for en in entities if en["placed"]];
162:     selected: dict | None = None;
163:     for en in entities {
164:         if en["id"] == selectedId {
165:             selected = en;
166:         }
167:     }
168:     selected_placed: bool = selected is not None and selected["placed"];
169:     selected_label: str = str(selected["label"]) if selected is not None else "";
170:     selected_note: str = str(selected["note"]) if selected is not None else "";
171: 
172:     return <main className="mc-shell">
173:         <header className="mc-header">
174:             <h1>Mindcraft</h1>
175:             <p>Name how you feel, give it a place on your island, and choose one gentle next step.</p>
176:         </header>
177:         {crisisMsg and <div className="mc-crisis" role="alert">
178:             <strong>You deserve support right now.</strong>
179:             <p>{crisisMsg}</p>
180:         </div>}
181:         <div className="mc-grid">
182:             <section className="mc-card">
183:                 <div className="mc-row" style={{"justifyContent": "space-between", "alignItems": "center"}}>
184:                     <h2>Your island</h2>
185:                     <button className="mc-btn" onClick={lambda { reset(); }}>Reset island</button>
186:                 </div>
187:                 <div className="mc-island" data-testid="island">
188:                     {if loading {
189:                         <div className="mc-island-empty">Loading your island...</div>
190:                     } elif len(placed) == 0 {
191:                         <div className="mc-island-empty">
192:                             <strong>Your island is empty</strong>
193:                             <span>Check in below, then place a feeling here.</span>
194:                         </div>
195:                     }}
196:                     {for en in placed {
197:                         <button
198:                             key={str(en["id"])}
199:                             className={"mc-entity is-selected" if en["id"] == selectedId else "mc-entity"}
200:                             style={{"left": str(en["x"]) + "%", "top": str(en["y"]) + "%", "background": en["color"]}}
201:                             onClick={lambda { select(str(en["id"])); }}
202:                         >{str(en["label"]) + " (" + str(en["intensity"]) + ")"}</button>
203:                     }}
204:                 </div>
205:                 <div className="mc-stack" style={{"marginTop": "12px"}}>
206:                     <span className="mc-label">Gentle interactions</span>
207:                     <div className="mc-row">
208:                         {for k in interactions {
209:                             <button key={k} className="mc-btn" disabled={not selected_placed} onClick={lambda { interact(k); }}>{k}</button>
210:                         }}
211:                     </div>
212:                     {if not selected_placed {
213:                         <span className="mc-muted">Select a placed feeling to try an interaction.</span>
214:                     }}
215:                 </div>
216:             </section>
217:             <aside className="mc-stack">
218:                 <section className="mc-card mc-stack">
219:                     <h2>Check in</h2>
220:                     <label className="mc-label" htmlFor="feel">How are you feeling?</label>
221:                     <textarea id="feel" className="mc-textarea" placeholder="I feel anxious about tomorrow and a bit tired" value={text} onChange={on_text} />
222:                     <button className="mc-btn mc-btn-primary" disabled={busy} onClick={lambda { check_in(); }}>Add check-in</button>
223:                     {error and <span className="mc-error">{error}</span>}
224:                     {notice and <span className="mc-muted">{notice}</span>}
225:                 </section>
226:                 <section className="mc-card mc-stack">
227:                     <h2>Waiting to be placed</h2>
228:                     {if len(pending) == 0 {
229:                         <span className="mc-muted">No pending feelings.</span>
230:                     }}
231:                     <div className="mc-pending">
232:                         {for (i, en) in enumerate(pending) {
233:                             <button key={str(en["id"])} className="mc-chip" onClick={lambda { place(str(en["id"]), len(placed) + i); }}>{"Place " + str(en["label"])}</button>
234:                         }}
235:                     </div>
236:                 </section>
237:                 {selected_placed and <section className="mc-card mc-stack">
238:                     <h2>{"Next step for " + selected_label}</h2>
239:                     <label className="mc-label" htmlFor="val">What matters to you here?</label>
240:                     <input id="val" className="mc-input" placeholder="Being prepared" value={value} onChange={on_value} />
241:                     <label className="mc-label" htmlFor="act">One concrete next action</label>
242:                     <input id="act" className="mc-input" placeholder="Write three bullet points for tomorrow" value={action} onChange={on_action} />
243:                     <button className="mc-btn mc-btn-primary" onClick={lambda { commit(); }}>Commit intention</button>
244:                     <span className="mc-label">Path</span>
245:                     {if pathLoaded and len(pathEvents) == 0 and len(pathActions) == 0 {
246:                         <span className="mc-muted">Placed. No interactions or intentions yet.</span>
247:                     }}
248:                     <ol className="mc-path">
249:                         <li>{"Felt: " + selected_note}</li>
250:                         <li>Placed on the island</li>
251:                         {for (i, ev) in enumerate(pathEvents) {
252:                             <li key={"ev" + str(i)}>{"Tried " + str(ev["kind"]) + ": " + str(ev["result"])}</li>
253:                         }}
254:                         {for (i, va) in enumerate(pathActions) {
255:                             <li key={"va" + str(i)}>{"Intention (" + str(va["value"]) + "): " + str(va["action"])}</li>
256:                         }}
257:                     </ol>
258:                 </section>}
259:             </aside>
260:         </div>
261:     </main>;
262: }

